ALTER TABLE products ADD COLUMN i18n JSONB NOT NULL DEFAULT '{}';

UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Spagetti", "tagline": "Sousni ushlab turadigan va yopishmaydigan klassika.", "description": "Uzun, tekis va elastik. Qattiq bug‘doydan, bronza matritsalardan o‘tkaziladi — sirti g‘adir-budir bo‘ladi va sous har bir tolaga yopishib qoladi. Qaynatilgan holda a’lo, ertasiga esa tuxum bilan qovurilgan holda.", "bestWith": ["Pomidor sousi", "Qaymoqli souslar", "Tuxum bilan qovurish"], "badge": "Xit"}'::jsonb) WHERE slug = 'spaghetti';
UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Penne", "tagline": "Ichiga sous yashirinadigan qirrali naychalar.", "description": "Qiya kesim, chuqur qirralar va qalin devor. Penne qozonda ham, tovada ham, duxovkada pishloq ostida ham ezilmaydi. Har qanday oshxonaning universal askari.", "bestWith": ["Zapekankalar", "Go‘shtli sous", "Sabzavotlar bilan qovurish"], "badge": "Xit"}'::jsonb) WHERE slug = 'penne';
UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Spiral", "tagline": "Uch o‘ram — uch baravar ko‘p sous.", "description": "Har qanday sous, pishloq yoki qovurilgan piyozni o‘ziga o‘rab oladigan zich spirallar. Salatlarda va tovada shaklini a’lo saqlaydi — kuchli olovda ham bo‘tqaga aylanmaydi.", "bestWith": ["Salatlar", "Pesto", "Pishloqli souslar"], "badge": ""}'::jsonb) WHERE slug = 'fusilli';
UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Kapalak", "tagline": "Bolalarning sevimlisi. Yashirincha — kattalarning ham.", "description": "Zich o‘rtasi va yupqa burma qanotchalari: bir porsiya — ikki xil tuzilish. Kapalaklar likopchada chiroyli ko‘rinadi va yengil qaymoqli souslarda a’lo ishlaydi.", "bestWith": ["Qaymoq va tovuq", "No‘xat", "Bolalar menyusi"], "badge": "Yangi"}'::jsonb) WHERE slug = 'farfalle';
UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Chig‘anoq", "tagline": "Har bir chig‘anoq — sous uchun kichik kosa.", "description": "Qirrali orqali chuqur chig‘anoqlar. Ichida sous, qiyma yoki erigan pishloq qoladi — har bir qoshiq to‘la bo‘ladi. Pishirish uchun a’lo.", "bestWith": ["Qiyma", "Pishloq", "Duxovkada pishirish"], "badge": ""}'::jsonb) WHERE slug = 'conchiglie';
UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Shoxcha", "tagline": "Bolalik ta’mi. Flotcha makaron tasdiqlaydi.", "description": "O‘sha shoxchalar. Tez qaynaydi, qiyma va piyoz bilan a’lo qovuriladi va eng shinam zapekankaning asosiga aylanadi. Bir qadoq — butun oila uchun kechki ovqat.", "bestWith": ["Flotcha", "Zapekanka", "Pishloq bilan"], "badge": "Xit"}'::jsonb) WHERE slug = 'elbow';
UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Rigatoni", "tagline": "Katta ishtaha uchun katta naychalar.", "description": "Qalin devorli yirik qirrali naychalar. Quyuq go‘shtli souslarni ushlab turadi va uzoq pishirishga chidaydi, elastikligini saqlagan holda.", "bestWith": ["Bolonyeze", "Duxovkada pishirish", "Quyuq souslar"], "badge": ""}'::jsonb) WHERE slug = 'rigatoni';
UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Uyacha", "tagline": "Ideal porsiyaga o‘ralgan keng lentalar.", "description": "Uyachalarga ehtiyotkorlik bilan joylangan talyatelle. Bir uyacha — bir porsiya, tarozi kerak emas. Keng lentalar qaymoqli souslar va qo‘ziqorinlar bilan ajoyib.", "bestWith": ["Qo‘ziqorin", "Qaymoq", "Qovurish"], "badge": "Premium"}'::jsonb) WHERE slug = 'nest';
UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Vermishel", "tagline": "Hamma narsani davolaydigan sho‘rva uchun.", "description": "Ingichka, tez, nozik. To‘g‘ridan-to‘g‘ri sho‘rvada 3 daqiqada tayyor bo‘ladi. Qaynatishdan oldin oltin rangga kirguncha qovursangiz — butunlay boshqa ta’m chiqadi.", "bestWith": ["Tovuq sho‘rva", "Sutli sho‘rva", "Qovurish"], "badge": ""}'::jsonb) WHERE slug = 'vermicelli';
UPDATE products SET i18n = jsonb_build_object('uz', '{"name": "Ugra", "tagline": "Buvijonnikidek, faqat polda unsiz.", "description": "Uy retsepti bo‘yicha keng tuxumli ugra. Lag‘mon, tovuq sho‘rva va vokda qovurish uchun — shaklini saqlaydi va ta’mni shimib oladi.", "bestWith": ["Lag‘mon", "Sho‘rva", "Vok"], "badge": ""}'::jsonb) WHERE slug = 'noodles';
